export interface RegistrationFields {
  contact: string;
  organization: string;
  role: string;
  givenName: string;
  familyName: string;
  summary: string;
  attachment: { name: string };
}

export type RegistrationErrors = {
  [K in keyof RegistrationFields]: string | null;
};

export interface RegistrationResult {
  valid: boolean;
  errors: RegistrationErrors;
}

export function validateRegistration(value: unknown): RegistrationResult {
  const data: Record<string, unknown> =
    typeof value === "object" && value !== null && !Array.isArray(value)
      ? value as Record<string, unknown>
      : {};
  const required = (name: string): string | null =>
    typeof data[name] === "string" && (data[name] as string).trim().length > 0
      ? null
      : "Required";
  const contact = typeof data.contact === "string" ? data.contact.trim() : "";
  const contactError = /^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/.test(contact)
    ? null
    : "Invalid contact";
  const summary = typeof data.summary === "string" ? data.summary.trim() : "";
  const attachment = data.attachment;
  const attachmentError =
    typeof attachment === "object" && attachment !== null && !Array.isArray(attachment) &&
    typeof (attachment as Record<string, unknown>).name === "string" &&
    ((attachment as Record<string, unknown>).name as string).trim().length > 0
      ? null
      : "Invalid attachment";
  const errors: RegistrationErrors = {
    contact: contactError,
    organization: required("organization"),
    role: required("role"),
    givenName: required("givenName"),
    familyName: required("familyName"),
    summary: summary.length >= 10 ? null : "Too short",
    attachment: attachmentError
  };
  return { valid: Object.values(errors).every(error => error === null), errors };
}

