import { validateRegistration } from './solution';

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  if (!Object.is(actual, expected)) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

const keys = ['contact', 'organization', 'role', 'givenName', 'familyName', 'summary', 'attachment'] as const;
function assertAllKeys(result: ReturnType<typeof validateRegistration>, message: string): void {
  equal(Object.keys(result.errors).sort().join(','), [...keys].sort().join(','), `${message} error keys`);
}
function assertInvalidField(result: ReturnType<typeof validateRegistration>, key: typeof keys[number], message: string): void {
  assert(typeof result.errors[key] === 'string' && result.errors[key]!.length > 0, `${message}: ${key} should have an error`);
}

const validInput = {
  contact: '  person@example.co.uk  ',
  organization: '  Acme  ',
  role: ' Engineer ',
  givenName: ' Ada ',
  familyName: ' Lovelace ',
  summary: '😀😀😀😀😀😀😀😀😀😀',
  attachment: { name: ' resume.pdf ' }
};
const before = JSON.stringify(validInput);
const valid = validateRegistration(validInput);
equal(valid.valid, true, 'valid registration');
assertAllKeys(valid, 'valid registration');
for (const key of keys) equal(valid.errors[key], null, `valid ${key}`);
equal(JSON.stringify(validInput), before, 'validation does not mutate input');

const invalidShapeValues: unknown[] = [null, [], 'text', 7, undefined];
for (const value of invalidShapeValues) {
  const result = validateRegistration(value);
  equal(result.valid, false, 'invalid root shape');
  assertAllKeys(result, 'invalid root shape');
  for (const key of keys) assertInvalidField(result, key, 'invalid root shape');
}

const missing = validateRegistration({});
equal(missing.valid, false, 'missing fields invalid');
for (const key of keys) assertInvalidField(missing, key, 'missing fields');

const whitespace = validateRegistration({
  contact: 'person@example.com', organization: '  ', role: '\n', givenName: '\t', familyName: '',
  summary: 'abcdefghij', attachment: { name: '   ' }
});
equal(whitespace.valid, false, 'whitespace required fields invalid');
for (const key of ['organization', 'role', 'givenName', 'familyName', 'attachment'] as const) assertInvalidField(whitespace, key, 'whitespace fields');
equal(whitespace.errors.contact, null, 'valid contact remains valid');
equal(whitespace.errors.summary, null, 'ten-code-point summary valid');

const badContacts = [
  'localdomain.com', 'a@@b.com', 'a b@c.com', 'a@b c.com', 'a@domain',
  'a@.domain.com', 'a@domain.com.', 'a @domain.com', ''
];
for (const contact of badContacts) {
  const result = validateRegistration({ ...validInput, contact });
  equal(result.valid, false, `bad contact ${contact}`);
  assertInvalidField(result, 'contact', `bad contact ${contact}`);
}

const nineCodePoints = validateRegistration({ ...validInput, summary: '😀😀😀😀😀😀😀😀😀' });
equal(nineCodePoints.valid, false, 'nine Unicode code points are insufficient');
assertInvalidField(nineCodePoints, 'summary', 'short Unicode summary');
const paddedTen = validateRegistration({ ...validInput, summary: '  1234567890  ' });
equal(paddedTen.errors.summary, null, 'summary length is measured after trimming');

for (const attachment of [null, [], {}, { name: '' }, { name: 12 }]) {
  const result = validateRegistration({ ...validInput, attachment });
  assertInvalidField(result, 'attachment', 'malformed attachment');
  equal(result.valid, false, 'malformed attachment invalidates result');
}

const frozen = Object.freeze({
  contact: 'x@y.co', organization: 'Org', role: 'Role', givenName: 'G', familyName: 'F',
  summary: '1234567890', attachment: Object.freeze({ name: 'a.txt' })
});
equal(validateRegistration(frozen).valid, true, 'frozen input can be validated without mutation');

